export type EditorialBoard = { id: unknown; slug: string; name: unknown; categories: string[] };
export type EditorialArchiveContext = { page: number; category: string | null; search: string | null };
export type EditorialPagination = { currentPage: number; lastPage: number | null; perPage: number; count: number; total: number | null; hasMorePages: boolean };
export type EditorialAuthor = { id: string | null; name: string | null; avatar: string | null; isGuest: boolean };
export type EditorialArticle = {
  id: number;
  href: string;
  title: string;
  excerpt: string | null;
  body: string | null;
  bodyMode: 'text' | 'html' | null;
  section: string | null;
  author: EditorialAuthor | null;
  createdAt: string | null;
  createdAtFormatted: string | null;
  visual: string | null;
};
export type EditorialPost = EditorialArticle;
export type EditorialContinuationItem = { id: number; title: string; href: string };
export type EditorialContinuation = { prev: EditorialContinuationItem | null; next: EditorialContinuationItem | null };
export type EditorialArticleStatus = 'invalid' | 'aborted' | 'unavailable' | 'forbidden' | 'not_found' | 'content';
export type EditorialFetch = (url: string, options: { method: 'GET'; credentials: 'omit'; headers: { Accept: 'application/json' }; signal?: AbortSignal }) => Promise<{ ok: boolean; status?: number; json: () => Promise<unknown> }>;
export const EDITORIAL_BOARD_CANDIDATES: readonly ['editorial', 'articles', 'stories', 'news'];
export const EDITORIAL_CONTENT_SOURCE: Readonly<{ provider: 'sirsoft-board' | null; board: string | null }>;
export const EDITORIAL_SEARCH_PARAM: 'search';
export const EMPTY_EDITORIAL_FEED: { selectedBoard: null; posts: readonly [] };
export const EMPTY_EDITORIAL_ARCHIVE: { selectedBoard: null; posts: readonly []; categories: readonly []; pagination: null; context: EditorialArchiveContext };
export const EMPTY_EDITORIAL_ARTICLE: { status: 'unavailable'; article: null };
export const EMPTY_EDITORIAL_CONTINUATION: EditorialContinuation;
export function isEditoriallyPublishable(post: unknown): boolean;
export function resolveEditorialBoard(options?: { fetchImpl?: EditorialFetch; signal?: AbortSignal }): Promise<EditorialBoard | null>;
export function resolveEditorialFeed(options?: { fetchImpl?: EditorialFetch; signal?: AbortSignal; pageSize?: number }): Promise<{ selectedBoard: EditorialBoard | null; posts: EditorialPost[] }>;
export function normalizeEditorialArchiveContext(value?: string | URLSearchParams | Record<string, unknown>): EditorialArchiveContext;
export function editorialArchiveHref(context?: string | URLSearchParams | Partial<EditorialArchiveContext>): string;
export function editorialDiscoveryCategories(selectedBoard: EditorialBoard | null, posts: readonly EditorialPost[]): readonly string[];
export function validateArticleId(value: unknown): number | null;
export function editorialArticleHref(value: unknown, context?: Partial<EditorialArchiveContext>): string | null;
export function resolveEditorialArchive(options?: { fetchImpl?: EditorialFetch; signal?: AbortSignal; pageSize?: number; context?: string | URLSearchParams | Record<string, unknown> }): Promise<{ selectedBoard: EditorialBoard | null; posts: EditorialPost[]; categories: string[]; pagination: EditorialPagination | null; context: EditorialArchiveContext }>;
export function resolveEditorialArticle(articleId: unknown, options?: { fetchImpl?: EditorialFetch; signal?: AbortSignal; context?: string | URLSearchParams | Record<string, unknown> }): Promise<{ status: EditorialArticleStatus; article: EditorialArticle | null; continuation?: EditorialContinuation }>;
